class Solution {
  private int[] mn, mx, lz;

  private void apply(int node, int v) {
    mn[node] += v;
    mx[node] += v;
    lz[node] += v;
  }

  private void push(int node) {
    if (lz[node] != 0) {
      apply(2 * node, lz[node]);
      apply(2 * node + 1, lz[node]);
      lz[node] = 0;
    }
  }

  private void update(int node, int lo, int hi, int l, int r, int v) {
    if (r < lo || hi < l) return;
    if (l <= lo && hi <= r) {
      apply(node, v);
      return;
    }
    push(node);
    int mid = (lo + hi) >>> 1;
    update(2 * node, lo, mid, l, r, v);
    update(2 * node + 1, mid + 1, hi, l, r, v);
    mn[node] = Math.min(mn[2 * node], mn[2 * node + 1]);
    mx[node] = Math.max(mx[2 * node], mx[2 * node + 1]);
  }

  private int findZero(int node, int lo, int hi, int limit) {
    if (lo > limit || mn[node] > 0 || mx[node] < 0) return -1;
    if (lo == hi) return lo;
    push(node);
    int mid = (lo + hi) >>> 1;
    int res = findZero(2 * node, lo, mid, limit);
    if (res >= 0) return res;
    return findZero(2 * node + 1, mid + 1, hi, limit);
  }

  public int longestBalanced(int[] nums) {
    int n = nums.length;
    mn = new int[4 * n];
    mx = new int[4 * n];
    lz = new int[4 * n];
    int[] last = new int[100_001];
    java.util.Arrays.fill(last, -1);
    int best = 0;
    for (int r = 0; r < n; r++) {
      int x = nums[r];
      update(1, 0, n - 1, last[x] + 1, r, x % 2 == 0 ? 1 : -1);
      last[x] = r;
      int l = findZero(1, 0, n - 1, r);
      if (l >= 0) best = Math.max(best, r - l + 1);
    }
    return best;
  }
}
